sys_ux_client_script.script:
/**
  * @param {params} params
  * @param {api} params.api
  * @param {TransformApiHelpers} params.helpers
  */
function evaluateProperty({api, helpers}) { var jsonObj = api.data.issue_locations.output; var numOfLoc = jsonObj.data.GlideAggregate_Query.length; var locArr = []; for (var i = 0; i < numOfLoc; i++) { var loc = { id: jsonObj.data.GlideAggregate_Query[i].groupBy[0].value, label: jsonObj.data.GlideAggregate_Query[i].groupBy[0].displayValue } locArr.push(loc); } return JSON.stringify(locArr); }
